            print(f"{'='*80}")
            if name in results:
                for k, v in results[name].items():
                    if k == "name":
                        continue
                    print(f"\n--- {k} ---")
                    print(v)
            else:
                print("NO DATA COLLECTED")


if __name__ == "__main__":
    main()

